parameters.jsCode:
// Extraer y formatear datos del lead de SoldeRío
const body = $input.item.json.body || $input.item.json;
const leadId = body.leadId || 'SOL-2026';
const cliente = body.cliente || {};
const dimension = body.dimensionamiento || {};

// Limpiar teléfono para WhatsApp (formato E.164: +569...)
let rawPhone = (cliente.whatsapp || '').replace(/[^0-9]/g, '');
if (rawPhone.startsWith('9') && rawPhone.length === 9) {
  rawPhone = '56' + rawPhone;
} else if (!rawPhone.startsWith('56') && rawPhone.length > 8) {
  rawPhone = '56' + rawPhone;
}

const ahorroFormateado = new Intl.NumberFormat('es-CL', {
  style: 'currency',
  currency: 'CLP',
  maximumFractionDigits: 0
}).format(dimension.estimatedAnnualSavingsClp || 0);

const gastoFormateado = new Intl.NumberFormat('es-CL', {
  style: 'currency',
  currency: 'CLP',
  maximumFractionDigits: 0
}).format(cliente.monthlyBillClp || 0);

// Mensaje para el cliente
const mensajeCliente = `¡Hola *${cliente.fullName}*! ☀️ Te saludamos del equipo de ingeniería de *SoldeRío*.

Hemos calculado tu pre-evaluación solar para tu propiedad en *${cliente.comuna || 'la Macrozona Sur'}*:

⚡ *Potencia recomendada:* ${dimension.recommendedKwp || 0} kWp (${dimension.panelsCount || 0} módulos Tier 1 N-Type)
🔋 *Almacenamiento:* ${dimension.batteryKwh > 0 ? dimension.batteryKwh + ' kWh LiFePO4 (<10ms en cortes)' : 'On-Grid Net Billing'}
💰 *Ahorro anual estimado:* ${ahorroFormateado}
🌲 *Huella de CO2:* -${dimension.co2TonsAvoidedPerYear || 0} Ton CO2/año

Un Ingeniero Eléctrico SEC Clase A revisará tu factibilidad técnica. ¿Te gustaría coordinar una visita a terreno?

👉 Responde a este chat o agenda tu visita en: https://solderio.cl/cotizacion`;

// Alerta interna para el equipo
const mensajeEquipo = `🚨 *NUEVO LEAD SOLAR - ${leadId}*

👤 *Cliente:* ${cliente.fullName}
📱 *WhatsApp:* +${rawPhone}
📍 *Ubicación:* ${cliente.comuna} (${cliente.propertyType})
💡 *Gasto actual:* ${gastoFormateado}/mes (${cliente.distributor})
☀️ *Propuesta:* ${dimension.recommendedKwp} kWp | Batería: ${dimension.batteryKwh} kWh
💵 *Ahorro proyectado:* ${ahorroFormateado}/año

👉 Contactar de inmediato: https://wa.me/${rawPhone}`;

return {
  leadId,
  phone: rawPhone,
  email: cliente.email,
  nombre: cliente.fullName,
  comuna: cliente.comuna,
  mensajeCliente,
  mensajeEquipo,
  dimensionamiento: dimension,
  rawLead: body
};

